 996	\begin{definition}[The concrete paired-line POVM]
 997		\label{def:concrete-paired-line-measurement}
 998		\lean{MIPStarRE.QPBT.ProjectiveSetting.combinedLineMeasurement}
 999		\lean{MIPStarRE.QPBT.ProjectiveSetting.combinedLineMeasurement_effect}
1000		\leanok
1001		\uses{def:expanded-line-measurement, def:povm-conventions,
1002			def:ideg-deg-polynomials}
1003		For any projective setting, either player, and any two source lines,
1004		define the POVM on the expanded local space by
1005		\[
1006			T^{\ell_X,\ell_Z}_{f_X,f_Z}
1007			=\hat M^{(\mathrm{Line},X),\ell_X}_{f_X}
1008			 \hat M^{(\mathrm{Line},Z),\ell_Z}_{f_Z}
1009			 \hat M^{(\mathrm{Line},X),\ell_X}_{f_X},
1010			\qquad (f_X,f_Z)\in\deg_{md}(\ell_X)\times\deg_{md}(\ell_Z).
