 290	\begin{lemma}[Non-encoding support estimate]
 291	\label{lem:qld-nonencoding-mass-bound}
 292		\lean{MIPStarRE.QPBT.nonencodingMarginalMass}
 293		\lean{MIPStarRE.QPBT.nonencodingMarginalMass_le}
 294		\uses{def:s-w-marginals, def:qld-full-field-decoder, def:expanded-state,
 295			lem:qld-4-7}
 296		For either player and either Pauli basis, the non-encoding marginal mass in
 297		Equation~\eqref{eq:qld-nonencoding-mass} is at most
 298		$\delta_P^{\mathrm{supp}}=C_{\mathrm{supp}}B$ for a universal
 299		$C_{\mathrm{supp}}\geq1$. This bound must be derived from point consistency and
 300		Schwartz--Zippel; it is not an additional extraction hypothesis.
